import{_ as a,o as l,c as e,a6 as d}from"./chunks/framework.B_q3ZJNF.js";const c=JSON.parse('{"title":"你的投资体系：一页纸计划书","description":"","frontmatter":{"title":"你的投资体系：一页纸计划书"},"headers":[],"relativePath":"astock-course/15-your-system.md","filePath":"astock-course/docs/15-your-system.md"}'),r={name:"astock-course/15-your-system.md"};function i(o,t,h,p,s,n){return l(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="你的投资体系-一页纸计划书" tabindex="-1">你的投资体系：一页纸计划书 <a class="header-anchor" href="#你的投资体系-一页纸计划书" aria-label="Permalink to &quot;你的投资体系：一页纸计划书&quot;">​</a></h1><p>先考你一道全书最短的题：合上书，三十秒内写出三行字——钱按什么比例分、什么条件才买、什么情况必须卖。写不满三行，不是你学得差，是十四章的道理还停在「知道」，没有变成规则。这门课的答案，最后就压在一张纸上：一页纸。</p><p>这门课到现在只回答一个问题：普通人进市场，凭什么长期赚钱。到这一章，回答它的零件已经全部备齐——前十四章攒下六十四块积木，本章再添两块，然后把全部积木装进一台不依赖当天心情的机器。机器叫投资体系——目标、配置、买卖规则、风控红线、复盘节奏的总和，检验标准是每条规则可检查、可执行、不依赖当天心情；图纸是一页纸，叫投资计划书——把个人投资体系写成的纸面契约，写完贴在看得见的地方，任何一笔操作前对照一遍，冲突就不做。</p><p>本章的路只有四段：先按五组对账六十四块积木，检查接口口径有没有漂移；再逐槽建立计划书的六个槽；然后回到第 1 章开篇那笔存款，用学完的一切重新演算；最后收束交卷。</p><h2 id="工具箱" tabindex="-1">工具箱 <a class="header-anchor" href="#工具箱" aria-label="Permalink to &quot;工具箱&quot;">​</a></h2><p>本章调用十块旧积木，按六个槽的次序过一遍接口。管钱怎么分的两块：资产配置——先定股债比例的顶层设计，长期收益的大头由它决定（第 10 章）；再平衡——比例偏离目标后卖超配、买低配，机械的低买高卖（第 10 章）。管什么时候进的三块：宽基指数——覆盖全市场多行业的指数，不押注单一行业（第 13 章）；定投——固定间隔投入固定金额，摊平成本、不猜底（第 11 章）；安全边际——先估内在价值区间，价格打到七折以下才出手（第 8 章）。</p><p>管出手与节制的三块：能力圈——三问自查，钱从哪来、谁在抢、亏了能否说清，答不上就是圈外（第 8 章）；仓位管理——单笔可亏额＝总资金 × 单笔风险预算，用（买入价 − 止损价）反推可买数量（第 11 章）；回本涨幅——亏损 ÷（1 − 亏损），亏得越深翻本越难（第 9 章）。管自己的三块：处置效应——盈利急着卖、亏损不肯卖，按成本价决策的毛病（第 12 章）；从众效应——跟随大多数人行动，顶部接盘、底部割肉（第 12 章）；损失厌恶——亏的痛约是赚的乐的两倍，该卖不卖、该买不买（第 12 章）。十一块全部就位，本章不新增散件，只做装订。</p><h2 id="对账-五组积木与五条稳定接口" tabindex="-1">对账：五组积木与五条稳定接口 <a class="header-anchor" href="#对账-五组积木与五条稳定接口" aria-label="Permalink to &quot;对账：五组积木与五条稳定接口&quot;">​</a></h2><p>对账先清点。前十四章的六十四块积木，按全书五个部分收成五组；每组管一件事，名录见表。</p><table tabindex="0"><thead><tr><th>组</th><th>章 · 块数</th><th>这组管什么</th><th>积木</th></tr></thead><tbody><tr><td>认知</td><td>第 1、2 章 · 10</td><td>钱的时间尺子；股价的两个因子</td><td>货币时间价值、复利、通货膨胀、实际购买力、收益率、股票、股权、市值、盈利、估值</td></tr><tr><td>规则</td><td>第 3–5 章 · 14</td><td>进场的规则与行情的读法</td><td>集合竞价、T+1、涨跌停板、印花税、佣金、过户费、K线、阳线与阴线、上影线与下影线、成交量、均线、趋势、支撑与压力、金叉与死叉</td></tr><tr><td>称重</td><td>第 6–8 章 · 17</td><td>公司的成色；价格的贵贱</td><td>资产负债表、利润表、现金流量表、毛利率、净利润、应收账款、货币资金、经营现金流、市盈率、盈利收益率、市净率、股息率、无风险利率、内在价值、安全边际、能力圈、护城河</td></tr><tr><td>活下来</td><td>第 9–12 章 · 16</td><td>亏得起；拿得住</td><td>波动率、最大回撤、盈亏不对称、回本涨幅、分散化、相关性、资产配置、再平衡、仓位、仓位管理、单笔风险预算、定投、损失厌恶、处置效应、锚定效应、从众效应</td></tr><tr><td>体系</td><td>第 13、14 章 · 7</td><td>主力武器；进场流程</td><td>指数、宽基指数、指数基金、ETF、费率、商业模式、研究清单</td></tr></tbody></table><p>清点之后验接口。对账的单位是积木，不是情节：你不需要记得哪一章讲过什么故事，只需要确认同一块积木在全书的用法没有变形。五组各举一例：</p><ul><li>认知组看复利。终值＝本金 ×（1 + 收益率）^年数——第 1 章算存款用它，第 13 章算两档费率二十年的差距，还是它。增长因子自始至终是同一个乘法，口径没动过。</li><li>规则组看三笔过路费。佣金价目表在第 3 章立起（课程示例值：万 2.5、单笔最低 5 元），第 5 章回测扣费用它，第 11 章定投核算还用它——同一串数字原样走完，一个值都没换。</li><li>称重组看存款锚。盈利收益率对照一年期存款挂牌利率，判定式在第 7 章立起；第 8 章称茅台用它，第 14 章清单第④步照抄，锚始终是同一条挂牌值（约 0.95%，2025-05-20，以银行最新挂牌为准）。</li><li>活下来组看回本涨幅。亏损 ÷（1 − 亏损）在第 9 章推导；第 11 章算深亏的补救难度用它，第 12 章给防御规则立论也用它——式子没变，变的只是代入的数。</li><li>体系组看定投核算。平均成本＝总投入 ÷ 累计份额，核算表在第 11 章立起；第 13 章把它原样跑满 240 期，一行未改，逐期对得上——旧接口照常工作，这就是口径稳定的机械证据。</li></ul><p>五组对账到此收口：积木齐，接口稳，剩下的工序只剩装订。逐词的完整定义不在这章复述，需要时去附录「术语表」按词查用。</p><h2 id="原理-把裁决权交给平静时的你" tabindex="-1">原理：把裁决权交给平静时的你 <a class="header-anchor" href="#原理-把裁决权交给平静时的你" aria-label="Permalink to &quot;原理：把裁决权交给平静时的你&quot;">​</a></h2><h3 id="没有体系-道理会在决策时刻失灵" tabindex="-1">没有体系，道理会在决策时刻失灵 <a class="header-anchor" href="#没有体系-道理会在决策时刻失灵" aria-label="Permalink to &quot;没有体系，道理会在决策时刻失灵&quot;">​</a></h3><p>先替临场判断说句公道话：信息足、情绪稳、时间宽裕的时候，临场应变甚至比规则更灵活——日常小额开销、亲友间借还钱，从来不需要计划书。它失效的边界在投资决策上：真正要按下单键的时刻，这三样恰好都不在。屏幕上行情跳动，浮亏时损失厌恶劝你「再等等」，小赚时处置效应劝你「先落袋」，群里热闹时从众效应递来「大家都在买」。道理你全懂，可那一刻握着鼠标的，不是懂道理的你。</p><p>反事实检验：假如道理本身够用，「体系」就是个多余的词。能验证的后果是——每次操作前现场重想一遍全部道理，而重想的心力恰好在行情剧烈时最稀缺；想不动的时候，人退回感觉办事。第 12 章四个陷阱全部埋伏在这条退路上。体系存在的成因因此只有一句：把裁决权从「当天的你」手里拿走，交还给「平静时写好规则的你们」。前十四章给了你全部的道理，本章把它们装订成规则——<strong>规则在平静时制定，在风暴时执行。</strong></p><p>「高手才需要体系」这个误区顺手拆掉：陷阱不挑智商，钱少的人反而更输不起——一次深套，要用好几年的结余去填。体系不会让你预测更准，它防的是你在最贵的时刻变笨。</p><h3 id="载体-一页纸与六个槽" tabindex="-1">载体：一页纸与六个槽 <a class="header-anchor" href="#载体-一页纸与六个槽" aria-label="Permalink to &quot;载体：一页纸与六个槽&quot;">​</a></h3><p>体系的载体是一页纸。长过一页，操作前你不会重读；盖不满六类裁决，就有一类决定留在现场拍脑袋。六个槽对应一次完整投资的全部裁决点：为什么投（目标）、钱怎么分（配置）、何时进（买入）、何时出（卖出）、什么绝不碰（红线）、多久查一次（复盘）。</p><p>计划书也不新造工具：你已有两份纸面工具——研究清单管「这一笔该不该买」（第 14 章），机械防御规则管「持有期间怎么不动摇」（第 12 章）；计划书是它们的合订本，把目标与配置装订进去，两份旧纸在同一个框架下生效。<strong>清单管一笔，计划书管整个账户。</strong></p><h2 id="计划书六槽-逐槽立标准" tabindex="-1">计划书六槽，逐槽立标准 <a class="header-anchor" href="#计划书六槽-逐槽立标准" aria-label="Permalink to &quot;计划书六槽，逐槽立标准&quot;">​</a></h2><p>每个槽给三样东西：装什么、判定句（可判定的填写标准）、写空形态（最常见的糊弄写法）。六道标准共用一条底线：每一条都要能被「符合 / 偏离」判定——<strong>可判定，是这一章唯一的写作标准。</strong></p><h3 id="槽1目标-为什么投" tabindex="-1">槽①目标：为什么投 <a class="header-anchor" href="#槽1目标-为什么投" aria-label="Permalink to &quot;槽①目标：为什么投&quot;">​</a></h3><p>装一条有数字、有期限、有验收方法的目标。判定句：到期那天，能用一条算式判出「达标 / 不达标」，验收尺用实际购买力（第 1 章），不看账户数字。写空形态：「跑赢通胀就行」「实现财务自由」——没有数字与期限，任何结果都能宣布达标。</p><p>示例：「20 年后，账户实际购买力不低于今天的 2 倍；每年末用物价因子折算验收一次。」跟算：购买力翻倍需要年化实际收益约 3.5%——2 的 20 次方根约等于 1.0353。这个数先记下，重考一节接它。</p><h3 id="槽2配置-钱怎么分" tabindex="-1">槽②配置：钱怎么分 <a class="header-anchor" href="#槽2配置-钱怎么分" aria-label="Permalink to &quot;槽②配置：钱怎么分&quot;">​</a></h3><p>装资产配置的落点：股债比例与再平衡规则。判定句：两侧比例加总等于 100%；每一侧点得到具体工具的名（宽基指数基金、存款与货币类，第 13 章）；再平衡写明日历日期或触发阈值（第 10 章）。写空形态：「主要买股票，适当留点存款」——「适当」没有分母，比例不封顶就不叫比例。</p><p>示例：「宽基指数基金 70%，存款与货币类 30%；每年 1 月第二个周末按目标比例再平衡。」</p><h3 id="槽3买入规则-何时进" tabindex="-1">槽③买入规则：何时进 <a class="header-anchor" href="#槽3买入规则-何时进" aria-label="Permalink to &quot;槽③买入规则：何时进&quot;">​</a></h3><p>装触发条件加动作，条件要能在日历或行情页上核对。判定句：主路径是定投——日期、金额、工具三项齐全（第 11、13 章）；个股通道设三重门槛——七步清单全过（第 14 章，清单第一步就是能力圈三问，圈外的票进不了清单）、价格落进七折线（第 8 章）、单笔预算装得下至少一手（第 11 章），三条同时成立才买。写空形态：「跌了就补一点」「感觉便宜再买」——「跌多少」没有数，「感觉」无法核对，是体系的禁用词。</p><p>示例：「每月发薪次日定投宽基指数基金 2000 元；个股仅在清单全过、七折线下、预算装得下一手三条同时成立时买入。」</p><h3 id="槽4卖出规则-何时出" tabindex="-1">槽④卖出规则：何时出 <a class="header-anchor" href="#槽4卖出规则-何时出" aria-label="Permalink to &quot;槽④卖出规则：何时出&quot;">​</a></h3><p>只认三类触发：基本面变坏（体检红旗，第 6 章）、价格过分（远超内在价值区间上沿，第 8 章；盈利收益率低得危险也算，第 7 章）、规则触发（止损单与再平衡，第 10、11 章）。判定句：每条判据的材料都取自公司、价格或规则，材料表里不许出现「我的成本价」——按成本价决策正是处置效应的病灶（第 12 章）。写空形态：「回本就卖」——判据是成本价；「涨够了自己会走」——「够」没有定义。</p><p>示例：「宽基底仓只在再平衡日调比例，期间涨跌都不操作；个股季度去留日复查，体检红旗升级即出；止损价事先写进持仓单，触发即执行。」</p><h3 id="槽5风控红线-什么绝不碰" tabindex="-1">槽⑤风控红线：什么绝不碰 <a class="header-anchor" href="#槽5风控红线-什么绝不碰" aria-label="Permalink to &quot;槽⑤风控红线：什么绝不碰&quot;">​</a></h3><p>至少三条，每条带具体数值：单笔风险预算（总资金的 1%–2%，第 11 章）、股票类总仓位上限（第 11 章）、组合回撤动作线（第 9 章）。判定句：数值与动作成对出现，触发与否是是非题。写空形态：「亏太多就止损」「注意控制回撤」——「太多」没有数，「注意」不是动作。</p><p>示例：「单笔亏损上限＝总资金 × 1%；股票类占比不超过 70%；组合自高点回撤 25% 时，暂停定投以外的一切买入，并对照②槽重估。」回撤线为什么必须带动作：亏 25% 之后回本要涨约 33%（25 ÷ 75，回本涨幅，第 9 章）——数字提前算好，深亏当天就没有谈判余地。</p><h3 id="槽6复盘节奏-多久查一次" tabindex="-1">槽⑥复盘节奏：多久查一次 <a class="header-anchor" href="#槽6复盘节奏-多久查一次" aria-label="Permalink to &quot;槽⑥复盘节奏：多久查一次&quot;">​</a></h3><p>装日期与对账单。判定句：复盘日是日历上查得到的日子；对账单逐槽记「符合 / 偏离」与偏离原因；记录状态只描述、不预测（第 5 章）。写空形态：「有空看看盘」——看盘不是复盘，它没有日期、没有产出物。</p><p>示例：「每季度最后一个周日核对持仓单与体检（季度去留日，第 12 章）；每年 1 月第二个周末再平衡并填年度对账单；修订计划书只发生在对账日，改了哪条、为什么改，留痕。」</p><p>「计划书写完就一劳永逸」这个误区在⑥槽就地证伪：公司会变，价格会变，你的收入也会变，从不修订的计划书会在第一次大偏离后整本作废；修订只放在对账日，是为了防止行情替你修订。</p><h2 id="演练-小周的一页纸-过六道验收" tabindex="-1">演练：小周的一页纸，过六道验收 <a class="header-anchor" href="#演练-小周的一页纸-过六道验收" aria-label="Permalink to &quot;演练：小周的一页纸，过六道验收&quot;">​</a></h2><p>示例人物小周：30 岁，总资金 6 万元，每月结余 3000 元（示意人物与示意数字，不构成任何建议）。他的计划书全文如下：</p><blockquote><p>①目标：20 年后账户实际购买力不低于今天的 2 倍，每年末用物价因子折算验收。</p><p>②配置：宽基指数基金 70%，存款与货币类 30%；每年 1 月第二个周末再平衡。</p><p>③买入：每月发薪次日定投宽基指数基金 2000 元；个股仅在清单全过、七折线下、预算装得下一手三条同时成立时买。</p><p>④卖出：宽基底仓只在再平衡日调比例；个股季度去留日复查，红旗升级即出，止损价事先写进持仓单。</p><p>⑤红线：单笔亏损上限＝总资金 × 1%，即 600 元；股票类占比不超过 70%；组合自高点回撤 25% 即暂停定投外的买入并重估。</p><p>⑥复盘：季度末周日核对，年度对账单逐槽记「符合 / 偏离」；修订只在对账日进行并留痕。</p></blockquote><p>六道验收逐槽过：</p><table tabindex="0"><thead><tr><th>槽</th><th>验收问题</th><th>判定</th></tr></thead><tbody><tr><td>①</td><td>有数字、有期限、有验收式？</td><td>通过——2 倍、20 年、物价因子折算</td></tr><tr><td>②</td><td>比例和为 100%，工具点得到名，再平衡有日期？</td><td>通过——70 + 30、宽基与货币类、1 月第二个周末</td></tr><tr><td>③</td><td>每条规则是条件加动作且可核对？</td><td>通过——定投三项齐全；个股三门槛并列</td></tr><tr><td>④</td><td>判据材料里没有成本价？</td><td>通过——红旗、区间上沿、止损单、再平衡</td></tr><tr><td>⑤</td><td>数值与动作成对？</td><td>通过——600 元、70%、25% 各带动作</td></tr><tr><td>⑥</td><td>日期查得到，对账单有产出？</td><td>通过——周日、逐槽判定、修订留痕</td></tr></tbody></table><p>再跟算一处积木的咬合：⑤槽的 600 元可亏额，接上仓位管理的反推式（第 11 章）。设小周看中一只 10 元的个股、止损价 8 元：每股风险 2 元，可买数量＝600 ÷ 2＝300 股，按手取整 3 手；300 股 × 10 元＝3000 元，占总资金 5%，远在 70% 上限之内。一条红线（⑤槽）接上反推公式（第 11 章）再接回预算门槛（③槽）——三块积木在同一次买入决策里咬合，这就是「体系」两个字的机械含义。</p><h2 id="验证-六份答卷-你来当考官" tabindex="-1">验证：六份答卷，你来当考官 <a class="header-anchor" href="#验证-六份答卷-你来当考官" aria-label="Permalink to &quot;验证：六份答卷，你来当考官&quot;">​</a></h2><p>判卷之前，先把六道判定句默写一遍，落纸。然后给下面六份已填条款写判词——「通过」或「写空」，写空的指出违反了哪道标准。判完再展开对照。</p><ol><li>目标：「希望 10 年后不必为钱发愁。」</li><li>配置：「股票 60%，剩下看情况再定。」</li><li>买入：「等行情企稳了，择机进场。」</li><li>卖出：「回本就卖，落袋为安。」</li><li>红线：「单笔亏损不超过总资金的 1%；组合回撤 25% 就暂停加仓。」</li><li>复盘：「每天收盘看一眼 K 线，做到心里有数。」</li></ol><details><summary>判卷答案</summary><ol><li>写空。没有数字、没有期限、没有验收式——十年后无论账户什么样，都能宣布「不愁」。</li><li>写空。「剩下看情况」让比例加总悬空，也不是 100%；再平衡无日期无阈值（第 10 章标准）。</li><li>写空。「企稳」「择机」无法核对；条件必须落在日历日期或行情页的具体读数上。</li><li>写空，且最危险。判据材料是成本价——处置效应由此坐上决策席（第 12 章）；合法触发只有基本面、估值、规则三类。</li><li>通过。两条都有数值与动作，是是非题；更完整的版本再补一条股票类总仓位上限。</li><li>写空。每天看盘没有日历日期、没有对账单、没有产出物；频率越高，裁决权越靠近当天的情绪——复盘要的是节奏，不是盯盘。</li></ol></details><p>迁移题：两年后小周收入翻倍、总资金翻倍，他的六槽里哪些数字要改，哪些规则不该动？</p><details><summary>迁移答案</summary><p>要改的是绝对值：定投金额、单笔可亏额（600 元变 1200 元）——它们是百分比乘上新基数。不该动的是规则本身：70/30、1% 预算、25% 回撤线、三类卖出触发、复盘日期。参数随人变，规则不随行情变；改规则只发生在对账日，并留痕。</p></details><h2 id="重考-第-1-章那笔存款-重新演算" tabindex="-1">重考：第 1 章那笔存款，重新演算 <a class="header-anchor" href="#重考-第-1-章那笔存款-重新演算" aria-label="Permalink to &quot;重考：第 1 章那笔存款，重新演算&quot;">​</a></h2><p>重考第 1 章开篇那笔账。2004 年存入 10 万元，2024 年取出 156050.92 元；按年均 3% 的示意通胀折算，实际购买力 86401.61 元——账面多了 56.05%，能买的东西少了 13.6%。当时的问题「钱到底是多了还是少了」，今天你能把输在哪里逐项点名：</p><ul><li>敌人是通胀：2.25% 的存款利率跑输 3% 的物价涨幅。复利在两侧同时开工——它不问好坏，只放大符号；购买力因子（1.0225 ÷ 1.03）连乘 20 次，只剩 0.864（第 1 章）。</li><li>监工缺席：这笔钱一次存入、二十年不动，没有目标、没有比例、没有复盘——不是存钱的人懒，是当年②槽和⑥槽还没造出来，输在了裸奔。</li><li>管道接错了：存款的收益贴着利率走；股市的长期回报走另一条管道——公司盈利（第 2 章：市值＝盈利 × 估值倍数，长期股价的锚是盈利）。宽基指数按规则买下一篮子公司的平均（第 13 章），这条管道对普通人开着。</li></ul><p>再跟算一遍反事实。同样的 10 万元、同样的二十年，换成第 1 章那条 6% 的示意复利线（教学示意收益率，不是任何承诺）：终值 320713.55 元；除以同一个物价因子 1.8061112，实际购买力约 177571.32 元，比本金多出 77.57%。验算用第 1 章那条心算式：名义 6% 减通胀 3%，每年留约 3 个百分点，1.03 连乘 20 次得 1.8061；精确因子是（1.06 ÷ 1.03）连乘 20 次，得 1.7757——近似式在这里把购买力高估了约 1.7%，通胀越高误差越大，这正是它在第 1 章被登记进「简化与差异清单」的原因。</p><p>现在把全书的题眼原文抄回，逐字作答——「零基础的普通人进A股，凭什么长期赚钱，而不是给市场送钱？」答案收口成一段：长期回报只有一个正当来路——企业盈利的增长乘上复利的时间（第 1、2 章）；普通人的全部功夫，是让自己始终留在这条管道上：宽基指数以低费率拿市场平均（第 13 章），安全边际约束出价（第 8 章），定投与仓位规则约束节奏与数量（第 11 章）；股债比例与回撤红线保证任何一年都不会被请出场（第 9、10 章）；一页纸计划书把裁决权从当天的情绪手里拿走（第 12 章、本章）。至于送钱的路——高费率、频繁换手的过路费、按成本价决策、顶部从众、深亏离场——每一条都被规则提前封死。<strong>普通人长期赚钱，凭的不是猜得更准，是送得更少。</strong></p><p>最后数一数现在的你，对照这门课出发时许下的终点：看得懂市场——竞价时点、T+1 的可卖日、K 线与趋势的读法、每笔交易的过路费，不再是天书；算得出估值——三张表体检、市盈率与安全边际，给任何一家公司称重；管得住风险——最大回撤先算，仓位先反推，红线先写死。合起来，就是你带走的那套可执行投资体系。它的期末考只有一道题：用一页纸计划书加七步清单，对一家真实公司完成一次完整决策，每一步留下可对照的产出。这道题没有标准答案，只有你的答案。</p><h2 id="收束-让规则替你上战场" tabindex="-1">收束：让规则替你上战场 <a class="header-anchor" href="#收束-让规则替你上战场" aria-label="Permalink to &quot;收束：让规则替你上战场&quot;">​</a></h2><p>回到开篇那道三十秒的考题。开篇写不满三行，是因为道理没有槽位；现在三问各有槽位、各有判定句——比例写进②槽，买点写进③槽，判据里不含成本价的卖出写进④槽，三行字合起来恰好一页纸。</p><p>本章新立的名字只有两个：投资体系——六槽的总和，检验标准是每条规则可检查、可执行、不依赖当天心情；投资计划书——它的一页纸载体，贴在看得见的地方，任何操作前对照，冲突就不做。五组对账里六十四块旧积木，加上这两块新名字，六十六块全部有了去处。写计划书最常见的失败不在写得少，在写不判：哪一槽出现「看情况」「差不多」「感觉」，哪一槽就是写空——任何结果都能宣布达标，规则就退回了心情。</p><p>体系不保证盈利。市场照旧会跌，红线照旧会触发，对账单照旧会记下「偏离」。它保证的是另一件事：十年后回头看，你的每一笔操作都能对上纸面规则——赢，说得出赢在哪条规则上；亏，说得出亏在哪条红线内。这份可回查，就是计划与下注的分界线。</p><p>延伸去向：盘点自己的积木缺口、规划 12 个月的进阶路径（第 16 章）。</p><h3 id="自查-五道对账题-翻回积木作答" tabindex="-1">自查：五道对账题，翻回积木作答 <a class="header-anchor" href="#自查-五道对账题-翻回积木作答" aria-label="Permalink to &quot;自查：五道对账题，翻回积木作答&quot;">​</a></h3><ol><li>六槽里哪一槽最常被写空？用该槽的判定句说明它为什么最容易被糊弄过去。</li><li>把小周的目标期限从 20 年改成 10 年、购买力目标仍是 2 倍，①槽隐含的年化实际收益变成约多少？目标变近了还是变难了？</li><li>一份计划书⑤槽写着「单笔预算 10%」。用第 11 章的预算思路说明：这条红线为什么形同虚设？</li><li>身边人都在晒单、从众警报拉响的那一周，计划书的哪些槽替你挡住了追高？各自怎么挡？</li><li>「投资体系是高手才需要的东西」——用①槽和⑤槽的判据各给一条反驳。</li></ol><details><summary>自查答案</summary><ol><li>④卖出。写它等于预先承认自己会看错，所以最容易被「回本就卖」「涨了再说」糊弄过去——前者的判据是成本价，后者根本没有判据；而④恰是处置效应唯一进不来的一道闸，写空它等于拆闸（第 12 章）。</li><li>约 7.2%（2 的 10 次方根约等于 1.0718）。期限减半，同样的目标要求接近翻倍的年化实际收益——目标不是变近，是变难。正确的动作是触发一次⑥槽对账、重估目标或期限，而不是硬改⑤槽的红线去迁就。</li><li>可亏额＝总资金 × 10%，连错十次本金即告清零；预算的本意是「错十次也只伤一成」。10% 意味着三连错就亏近三成，按回本涨幅要涨四成多才回本（第 9 章）——红线失去了「保证在场」的功能，只留下「保证亏得快」。</li><li>③槽：新增买入必须有触发条件，「大家都在买」不在基本面、估值、规则任何一类的合法触发里；②⑤槽：70/30 的目标比例与 70% 的仓位上限封死了追高的空间；⑥槽：修订只发生在对账日，警报当周只能记录、不能行动。</li><li>①槽：目标越普通（保值、养老、教育金），越需要验收式，否则连「有没有变穷」都判不出——这与高不高手无关，是写与不写的区别。⑤槽：红线保护的恰恰是输不起的小资金——钱少、可亏额小、一次深套要用多年结余去填，第 12 章的陷阱也从不挑智商。</li></ol></details><blockquote><p>本课程全部内容仅用于学习交流，不构成任何投资建议；不荐股、不承诺收益、不代客理财。文中利率、费率、通胀率等数字有时效，以最新公告为准；示例均为教学示意，市场有风险，决策须独立。</p></blockquote>',69)])])}const b=a(r,[["render",i]]);export{c as __pageData,b as default};
